Hook.Script:
//
// Set up variables for "override getnext" hook
//

var root = xmldom.getDocumentElement ();
var list = system.selectNodeList ( root, XMLInput.connector.getParser().getParam("xmlEntryTag") );
var counter = 0;

if ( counter < list.getLength() )
  nxt = list.item ( counter );
else
  nxt = null;

if ( nxt != null ) {
    var ch = nxt.getFirstChild();
    while ( ch != null ) {    // parse the first level of the XML document
        var nodeValue = ch.getNodeValue();
        if (nodeValue != null) {
			if (nodeValue.indexOf("\n") == -1)
            	entry.setAttribute ( ch.getNodeName(), nodeValue );
		}
        else {    // parse the second level of the XML document (if such exist)
			var chNode = ch.getFirstChild();
			var attr = system.newAttribute(ch.getNodeName());
			while ( chNode != null ) {
				var chNodeValue = chNode.getNodeValue();
				if (chNodeValue != null) {
					if (chNodeValue.indexOf("\n") == -1)
						attr.addValue(chNodeValue);
				} else {    // parse the third level of the XML document (if such exist)
					var chNode2 = chNode.getFirstChild();
					var attr2 = system.newAttribute(chNode.getNodeName());
					while ( chNode2 != null ) {
						var chNodeValue2 = chNode2.getNodeValue();
						if (chNodeValue2 != null && chNodeValue2.indexOf("\n") == -1) {
							attr2.addValue(chNodeValue2);
						}
						chNode2 = chNode2.getNextSibling();
					}
					attr.addValue(attr2);
				}
				chNode = chNode.getNextSibling();
			}
			entry.setAttribute( ch.getNodeName(), attr );
        }
        ch = ch.getNextSibling();
    }
    result.setStatus (1);
	counter++;
} 
else {
    result.setStatus (0);
}

var root = xmldom.getDocumentElement ();
var entry = xmldom.createElement ( XMLOutput.connector.getParser().getParam("xmlEntryTag") );
var names = work.getAttributeNames ();

for ( var i = 0; i < names.length; i++ ) {    // process the first level of the Attributes structure
	var node = xmldom.createElement ( names[i] );
	var values = work.getAttribute ( names[i] ).getValues ();

	for ( var j = 0; j < values.length; j++ ) {    // process the second level of the Attributes structure
		var element = values[j];
		if ( ! element.getClass().getName().equals("com.ibm.di.entry.Attribute") ) {
			if ( work.getAttribute(names[i]).size() > 1 ) {
				var medial_node = xmldom.createElement ( XMLOutput.connector.getParser().getParam("xmlValueTag") );
				node.appendChild ( medial_node );
				medial_node.appendChild ( xmldom.createTextNode ( attribute.getValue (i) ) );
			}
			else {
				node.appendChild ( xmldom.createTextNode ( values[j] ) );
			}
		}
		else {    // process the third level of the Attributes structure
			var childNode = xmldom.createElement ( element.getName () );
			var elValues = element.getValues ();
			for ( var k = 0; k < elValues.length; k++ ) {
				if (element.size() > 1) {
					var medial_node_2 = xmldom.createElement ( XMLOutput.connector.getParser().getParam("xmlValueTag") );
					childNode.appendChild ( medial_node_2 );
					medial_node_2.appendChild ( xmldom.createTextNode ( elValues[k] ) );
				}
				else {
					childNode.appendChild ( xmldom.createTextNode ( elValues[k] ) );
				}
			}
			node.appendChild ( childNode );
		}
		entry.appendChild ( node );
	}
}
root.appendChild ( entry );
